\begin{lemma}
\label{lem:dd_failure}
For doubly stochastic $C_0$, condition~\eqref{eq:dd_condition} requires:
\[
  \left(\frac{\alpha_j}{1-\alpha_j}\right)^2 \geq \frac{\max_k p_k}{\min_k p_k}.
\]
\end{lemma}

\begin{proof}
